fn main () -> Result < () > { let args = Args :: parse () ; println ! ("🧠 Lisp-like Macro System for Output2") ; match args . command . as_str () { "import" => { let mut system = Output2MacroSystem :: import_from_output2 () ? ; system . overlay_wrappers () ; println ! ("✅ Imported {} macros from output2" , system . macros . len ()) ; for (name , decl) in system . macros . iter () . take (5) { println ! ("  📦 {}: {} ({})" , name , decl . declaration_type , decl . source_path) ; } } , "doc" => { let mut system = Output2MacroSystem :: import_from_output2 () ? ; system . overlay_wrappers () ; let doc = system . generate_rustdoc () ? ; std :: fs :: write ("output2_macros.md" , & doc) ? ; println ! ("📚 Generated rustdoc: output2_macros.md") ; println ! ("📊 {} total callable macros" , system . macros . len ()) ; } , "eval" => { let mut system = Output2MacroSystem :: import_from_output2 () ? ; system . overlay_wrappers () ; for expr in & args . expressions { println ! ("🧠 Evaluating: {}" , expr) ; let result = system . interpreter . eval (expr) ? ; println ! ("  ✅ Result: {:?}" , result) ; } } , "generate" => { let mut system = Output2MacroSystem :: import_from_output2 () ? ; system . overlay_wrappers () ; let blob = RdfUrlBlob :: from_system_state (& system) ? ; blob . print_url () ; } , "export" => { let blob = if args . expressions . is_empty () { RdfUrlBlob :: from_stdin () ? } else { RdfUrlBlob :: from_url_blob (& args . expressions [0]) ? } ; let capability = args . expressions . get (1) . map (| s | s . as_str ()) . unwrap_or ("macros") ; let exported = blob . export (capability) ? ; println ! ("{}" , exported) ; } , "rustc" => { println ! ("🦀 Creating eigenmatrix of rustc compiler...") ; let rustc_path = Path :: new ("/mnt/data1/nix/vendor/rust/cargo2nix/submodules/rust") ; if ! rustc_path . exists () { return Err (anyhow :: anyhow ! ("Rustc source not found at: {:?}" , rustc_path)) ; } let mut rustc_matrix = RustcEigenmatrix :: analyze_rustc (rustc_path) ? ; rustc_matrix . compute_eigenform () ? ; rustc_matrix . print_analysis () ; rustc_matrix . matrix . print_matrix (15 , 8) ; let eigenmatrix_url = rustc_matrix . to_eigenmatrix_url () ? ; println ! ("\n🧮 Rustc Eigenmatrix URL:") ; println ! ("{}" , eigenmatrix_url) ; } , _ => { println ! ("❌ Unknown command: {}" , args . command) ; println ! ("Available commands:") ; println ! ("  import    - Import output2 as macros") ; println ! ("  doc       - Generate rustdoc") ; println ! ("  eval      - Lisp evaluation") ; println ! ("  generate  - Generate RDF URL blob") ; println ! ("  export    - Export from RDF blob (stdin or arg)") ; println ! ("  matrix    - Create URL matrix and compress to eigenform") ; println ! ("  rustc     - Create eigenmatrix of rustc compiler") ; println ! ("  info      - Show RDF blob info") ; } } Ok (()) }